    const plotsS = plotSlides(opt, items, lib || {N: null});
    const upS = []; const ups = d.uploads.filter(u => ms.upSel.has(u.fileId));
    for (let i = 0; i < ups.length; i += opt.per) { const ch = ups.slice(i, i + opt.per), n = ch.length, lid = D.recommend(n, opt.stype === 'tp'); const s = D.newSlide(lid, {title: n === 1 ? ch[0].name.replace(/\.[^.]+$/, '') : `Figures ${i + 1}–${i + n}`, origin: 'gen', gen: {kind: 'uploads', ids: ch.map(c => c.fileId)}}); s.images = ch.map(c => ({src: upSrc(c)})); upS.push(s); }
