    const warns = d.slides.map((s, i) => D.slideWarnings(s, d).length ? i + 1 : 0).filter(Boolean);
    if (empt.length) out.push(`${empt.length} text slide${empt.length === 1 ? ' has' : 's have'} no text yet (slide${empt.length === 1 ? '' : 's'} ${empt.join(', ')}). They will export with only a title.`);
    if (stale) out.push(`${stale} slide${stale === 1 ? ' uses' : 's use'} a plot that has a newer version. Open the slide to keep, replace or compare.`);
